#!/bin/bash
# Generated by image-composer-tool. Runs the OEP Installer (openedge-cli) on
# first boot for the image's modules, as the image template's user. The
# provisioning unit runs this script again at the next boot only when it was
# stopped by a reboot. openedge-cli schedules its own reboot ("shutdown -r +2")
# and then waits, so the shutdown stops this script rather than it exiting. When
# openedge-cli fails, the unit records the failure, is not run again at boot,
# and the login prompt tells an administrator to fix the problem and run
# "ict-provision-report retry oep-installer", which starts the unit again (so
# this script runs again, as the same user with the temporary sudo grant).
#
# Arguments: the modules and arguments for "openedge-cli install".
# Environment: OEP_INSTALLER_USER (the user), OEP_INSTALLER_CLI (the CLI file).
set -euo pipefail

user="${OEP_INSTALLER_USER:?}"
cli="${OEP_INSTALLER_CLI:?}"
grant_dir=/run/ict-oep-installer.d
sudoers="$grant_dir/grant"

# openedge-cli runs its privileged steps through "sudo -n". Allow that only
# while this script runs. The grant is in /run, which /etc/sudoers.d includes
# (see the image's 90-ict-oep-installer file), so a reboot also removes it,
# even on an image whose /etc persists across boots.
cleanup() { rm -f "$sudoers" "$sudoers.tmp"; }
trap cleanup EXIT
trap 'exit 143' TERM INT HUP
# The image's tmpfiles.d entry creates this directory at boot; create it here too
# in case the script is run on its own.
install -d -m 0755 "$grant_dir"
printf '%s ALL=(ALL) NOPASSWD: ALL\n' "$user" >"$sudoers.tmp"
chmod 0440 "$sudoers.tmp"
visudo -cqf "$sudoers.tmp"
mv "$sudoers.tmp" "$sudoers"

home="$(getent passwd "$user" | cut -d: -f6)"
cd "$home"
# Each step runs in the background so a stop signal reaches the traps at once
# instead of after the step exits; wait returns the step's exit status.
as_user() {
	runuser -u "$user" -- env HOME="$home" USER="$user" LOGNAME="$user" "$@" &
	wait "$!"
}

# setup saves the CLI as ~/.local/bin/openedge-cli and adds bash completion.
as_user bash "$cli" setup
as_user "$home/.local/bin/openedge-cli" install "$@"
